import sys

def main():
    import sys
    input = sys.stdin.read().splitlines()
    t = int(input[0])
    index = 1
    results = []
    for _ in range(t):
        s = input[index]
        c = input[index + 1].strip()
        index += 2
        if len(s) == 1:
            results.append("YES" if s == c else "NO")
        else:
            count = s.count(c)
            if count % 2 == 1:
                results.append("YES")
            else:
                results.append("NO")
    print("\n".join(results))

if __name__ == "__main__":
    main()
